package main

import (
	"fmt"
	"sync"
)

func main() {
	var counter int
	var wg sync.WaitGroup
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 1000; j++ {
				counter++ // DATA RACE: unsynchronized read-modify-write
			}
		}()
	}
	wg.Wait()
	fmt.Println(counter) // often < 2000, and non-deterministic
}
